const one = (prompt, answer, options, explanation) => ({ type: 'single', prompt, answer, options, explanation })
const many = (prompt, answer, options, explanation) => ({ type: 'multi', prompt, answer, options, explanation })
const date = (prompt, answer, explanation) => ({ type: 'date', prompt, answer, explanation })
const text = (prompt, answer, explanation) => ({ type: 'text', prompt, answer, explanation })
const match = (prompt, pairs, explanation) => ({
  type: 'match',
  prompt,
  pairs,
  answer: pairs.map((pair) => pair.answer),
  explanation,
})
const pair = (label, answer, alternatives) => ({ label, answer, options: [answer, ...alternatives] })
const work = (id, title, unit, description, questions, olympiad = false) =>
  ({ id, title, unit, description, questions, ...(olympiad ? { olympiad: true } : {}) })

